{
  "name": "@allansantos-dev/opencode-memory",
  "version": "0.4.1",
  "description": "OpenCode plugin — persistent memory across sessions via mcp-memory-server.",
  "type": "module",
  "license": "MIT",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AllanSantos-DV/opencode-memory.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "recall",
    "graph",
    "curation",
    "knowledge-base"
  ],
  "engines": {
    "opencode": "^1.18.0"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json && esbuild src/index.ts --bundle --platform=node --format=esm --outfile=dist/index.js",
    "typecheck": "tsc --noEmit",
    "test": "node --import tsx --test test/*.test.ts && node --import tsx test/smoke.ts",
    "verify-pack": "node scripts/verify-pack.mjs",
    "prepack": "npm run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.21",
    "@types/node": "^26.1.2",
    "esbuild": "^0.25.12",
    "tsx": "^4.19.0",
    "typescript": "^6.0.3",
    "zod": "^4.1.8"
  }
}
